package com.alpharip.staffmod.BuildTimelapse.camera;
public final class CameraController {private final CameraRuntimePort runtime;private final CameraPathInterpolator interpolator=new CameraPathInterpolator();private CameraPose pose=CameraPose.origin();private CameraMode mode=CameraMode.FREE;private CameraPath path;private long pathStart;private boolean active;
 public CameraController(CameraRuntimePort r){if(r==null)throw new IllegalArgumentException();runtime=r;}public synchronized void activate()throws Exception{if(!runtime.isAvailable())throw new IllegalStateException("Camera bridge missing");runtime.activate(pose);active=true;}
 public synchronized void setPose(CameraPose p)throws Exception{if(p==null)throw new IllegalArgumentException();pose=p;if(active)runtime.apply(p);}public synchronized CameraPose getPose(){return pose;}public synchronized void setMode(CameraMode m){mode=m;}public synchronized CameraMode getMode(){return mode;}
 public synchronized void playPath(CameraPath p,long now){if(p==null||p.getWaypoints().size()<2||p.duration()==0)throw new IllegalArgumentException("Path needs two timed points");path=p;pathStart=now;mode=CameraMode.PATH;}
 public synchronized void tick(long now)throws Exception{if(!active||path==null)return;double f=Math.min(1d,(double)(now-pathStart)/path.duration());setPose(interpolator.sample(path,f));if(f>=1)path=null;}public synchronized void stopPath(){path=null;}public synchronized void deactivate()throws Exception{if(active)runtime.deactivate();active=false;path=null;}public synchronized boolean isActive(){return active;}
}
